def gen(rng):
    def word(alpha, mx):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(1, mx)))
    def fmt(a, b):
        return f"{len(a)} {len(b)}\n" + ' '.join(a) + "\n" + ' '.join(b)
    tests = [fmt(['a'], []), fmt([], ['b']), fmt(['a', 'a'], ['a']), fmt(['a', 'ab'], ['aa', 'abc']),
             fmt(['good', 'person'], ['he', 'is']), fmt(['x', 'y', 'z'], ['a', 'b'])]
    for _ in range(14):
        alpha = rng.choice(['ab', 'abc', 'abcdefghij'])
        n = rng.randint(0, 12); m = rng.randint(0, 12)
        if n + m == 0:
            n = 1
        a = sorted(word(alpha, 4) for _ in range(n))
        b = sorted(word(alpha, 4) for _ in range(m))
        tests.append(fmt(a, b))
    big = 'abcdefghijklmnopqrstuvwxyz'
    for n, m, alpha, mx in [(100000, 100000, big, 8), (100000, 1, big, 8), (60000, 100000, 'ab', 8), (50000, 50000, 'abc', 8)]:
        a = sorted(word(alpha, mx) for _ in range(n))
        b = sorted(word(alpha, mx) for _ in range(m))
        tests.append(fmt(a, b))
    return tests

